<div class="page-bar"><ul class="page-breadcrumb"><li><a href="/<?= ADM_CONTROLLER ?>/">Главная</a><i class="fa fa-circle"></i></li><li><span>Партнёрская программа</span></li></ul></div>
<h1 class="page-title">Обращения креаторов</h1>
<form method="get" class="form-inline" style="margin:16px 0 20px"><label for="creator-feedback-status">Статус</label> <select id="creator-feedback-status" class="form-control" name="status"><option value="">Все</option><?php foreach ($labels as $key => $label) { ?><option value="<?= $key ?>" <?= $selected_status === $key ? 'selected' : '' ?>><?= $label ?></option><?php } ?></select> <button class="btn blue" type="submit">Показать</button></form>
<div class="portlet light"><div class="portlet-title"><div class="caption"><i class="fa fa-comments-o"></i> Обращения (<?= count($rows) ?>)</div></div><div class="portlet-body table-responsive"><table class="table table-striped table-bordered"><thead><tr><th>Получено</th><th>Креатор</th><th>Email</th><th>Тема</th><th>Сообщение</th><th>Статус</th><th></th></tr></thead><tbody>
<?php if (!$rows) { ?><tr><td colspan="7" class="text-center">Обращений нет.</td></tr><?php } ?>
<?php foreach ($rows as $row) { ?><tr><td><?= html_escape($row['created_at']) ?></td><td>#<?= (int) $row['client_id'] ?> · <?= html_escape($row['name'] ?: '—') ?></td><td><?= html_escape($row['email'] ?: '—') ?></td><td><?= html_escape($topics[$row['topic']] ?? $row['topic']) ?></td><td><?= html_escape(mb_strimwidth($row['message'], 0, 140, '…', 'UTF-8')) ?></td><td><span class="label label-<?= $row['status'] === 'new' ? 'warning' : ($row['status'] === 'closed' ? 'success' : 'info') ?>"><?= $labels[$row['status']] ?? html_escape($row['status']) ?></span></td><td><a class="btn btn-sm blue" href="/<?= ADM_CONTROLLER ?>/creator_feedback/view/<?= (int) $row['id'] ?>">Открыть</a></td></tr><?php } ?>
</tbody></table></div></div>
